const entrada = $('Edit Fields').first().json;
const respuesta = $input.first().json.output;

let datos;
try {
  datos = typeof respuesta === 'string'
    ? JSON.parse(respuesta)
    : respuesta;
} catch {
  throw new Error('Recepción detenida: la respuesta no es JSON válido.');
}

if (!datos || typeof datos !== 'object' || Array.isArray(datos)) {
  throw new Error('Recepción detenida: estructura inválida.');
}

const estados = ['validado', 'requiere_aclaracion', 'rechazado'];

if (
  datos.caso_id !== entrada.caso_id ||
  datos.agente !== 'recepcion' ||
  datos.modo !== 'SIMULADO' ||
  !estados.includes(datos.estado) ||
  !Array.isArray(datos.productos) ||
  !Array.isArray(datos.faltantes) ||
  !Array.isArray(datos.advertencias)
) 
  throw new Error(JSON.stringify({
  folioOriginal: entrada.caso_id,
  folioRespuesta: datos.caso_id,
  folioCoincide: datos.caso_id === entrada.caso_id,
  agenteCorrecto: datos.agente === 'recepcion',
  modoCorrecto: datos.modo === 'SIMULADO',
  estadoCorrecto: estados.includes(datos.estado),
  productosEsLista: Array.isArray(datos.productos),
  faltantesEsLista: Array.isArray(datos.faltantes),
  advertenciasEsLista: Array.isArray(datos.advertencias)
}));

if (datos.estado === 'validado') {
  const productosValidos =
    datos.productos.length > 0 &&
    datos.productos.every(p =>
      typeof p.producto === 'string' &&
      p.producto.trim().length > 0 &&
      Number.isInteger(p.cantidad) &&
      p.cantidad > 0
    );

  if (!productosValidos || datos.faltantes.length > 0) {
    throw new Error('Recepción detenida: pedido incompleto o cantidades inválidas.');
  }
}

if(datos.estado!=='validado')throw Error('REQUIERE_ACLARACION');
return [{
  json: {
    ...entrada,
    recepcion: datos,
    validacion_recepcion: 'aprobada'
  }
}];

